import json,pathlib
root=pathlib.Path('/workspace/sites/olympiad-atlas'); out=root/'data/americas.json'
bank=[x for x in json.load(open(out)) if x['country']!='United States']
rows=[]
def add(y,n,d,t,tags,statement,reason,slug=None,comp='USAMO',appearances=None,solution=None):
 u=f'https://web.evanchen.cc/exams/{"JMO" if comp=="USAJMO" else "USAMO"}-{y}-notes.pdf'
 row=dict(id=f'us-{comp.lower()}-{y}-{n}',country='United States',competition=comp,year=y,number=str(n),statement=statement,solution=solution or f'[View Evan Chen’s worked solution notes (PDF)]({u}). Find {comp} {y}, Problem {n}.',sourceUrl=u,solutionUrl=u,topic=t,tags=tags,difficulty=d,ratingReason=reason,reviewStatus='individually-assessed',solutionKind='original-exposition' if solution else 'source-link',notes='Mathematical statement paraphrased. Difficulty assessed from the actual argument; solution notes are an author-maintained reference, not an official MAA document.')
 if slug:row['secondarySourceUrl']=f'https://mathnet.mit.edu/data_v2/full/united-states/{slug}.json.gz'
 if appearances:row['appearances']=appearances
 rows.append(row)
add(2006,1,5.5,'Number Theory',['modular arithmetic','fractional parts','construction'],r'For a prime $p$ and an integer $s$ with $0<s<p$, prove the following equivalence: there are integers $0<m<n<p$ for which $\{sm/p\}<\{sn/p\}<s/p$ if and only if $s\nmid p-1$. Here $\{x\}=x-\lfloor x\rfloor$.','Requires ordering the small nonzero residues of multiples of s, then choosing the first wraparound and the residue s−1. The reverse direction needs an explicit description when s divides p−1.','usa_2006_da8d07')
add(2006,2,6,'Combinatorics',['extremal','integer inequalities'],r'Fix a positive integer $k$. Determine the least real number $N$ such that some $2k+1$ distinct positive integers have total sum greater than $N$, while every choice of $k$ of them has sum at most $N/2$.','The largest k terms give a useful bound, but the sharp result needs both sides of the median, integer rounding, and a consecutive-integer equality construction.','usa_2006_9454b3')
add(2006,4,6.5,'Algebra',['AM-GM','rational numbers','construction'],r'Find all positive integers $n$ for which there are $k\ge2$ positive rational numbers satisfying $a_1+\cdots+a_k=a_1\cdots a_k=n$.','AM–GM rules out small n; finding families for even and odd n and handling the exceptional value 7 is the main creative burden. Rationality also matters in the two-variable exclusion.','usa_2006_0a860b')
add(2006,6,6.5,'Geometry',['spiral similarity','concyclicity'],r'In quadrilateral $ABCD$, choose $E\in AD$ and $F\in BC$ with $AE/ED=BF/FC$. Suppose ray $FE$ meets rays $BA$ and $CD$ at $S$ and $T$. Show that the four circumcircles $(SAE),(SBF),(TCF),(TDE)$ share a point.','Choose the second intersection of two circles, extract a spiral similarity, and transfer it using the equal side ratios. Several linked angle and ratio steps make this harder than a direct circle chase.','usa_2006_688c96')
add(2007,1,4.5,'Number Theory',['sequences','invariants','monotonicity'],r'Start with $a_1=n$, where $n$ is a positive integer. For $k>1$, choose the unique integer $a_k\in\{0,1,\ldots,k-1\}$ making $a_1+\cdots+a_k$ divisible by $k$. Prove that the sequence eventually becomes constant.','The decisive change of viewpoint is to the integer averages of the partial sums. Showing those averages are positive and nonincreasing gives a short stabilization proof.','usa_2007_83a6e7')
add(2007,3,7,'Combinatorics',['induction','sets','extremal'],r'Let $n$ be a positive integer and let $S$ contain $n^2+n-1$ elements. Colour every $n$-element subset of $S$ red or blue. Prove that $n$ pairwise disjoint subsets have the same colour.','A direct induction does not preserve the parameters. Strengthening to (n+1)m−1 elements and finding two differently coloured sets differing in one element produces the right induction step.','usa_2007_92862a')
add(2007,4,7,'Combinatorics',['graphs','polyominoes','extremal'],r'A polyomino is a finite union of unit grid squares connected through shared edges. Call one with at least $2007$ squares a dinosaur. It is primitive if its squares cannot be partitioned into two or more dinosaurs. Find the greatest possible number of squares in a primitive dinosaur.','The cross construction suggests a sharp bound, but the proof needs a spanning tree and a suitable separating vertex or edge. Translating connectivity into that tree argument is the substantial insight.','usa_2007_f4d07c')
add(2008,1,6,'Number Theory',['induction','coprimality','factorisation'],r'For every positive integer $n$, prove that there exist pairwise coprime integers $k_0,\ldots,k_n>1$ such that $k_0k_1\cdots k_n-1$ is a product of two consecutive integers.','An inductive construction comes from the non-obvious factorization (a²−a+1)(a²+a+1)=a⁴+a²+1. One must check that the added factor is coprime to the entire old product.','usa_2008_91e70b')
add(2008,2,6.5,'Geometry',['circumcentre','concyclicity','similarity'],r'In an acute scalene triangle $ABC$, let $M,N,P$ be the midpoints of $BC,CA,AB$. The perpendicular bisectors of $AB$ and $AC$ meet ray $AM$ at $D$ and $E$, respectively. Lines $BD$ and $CE$ meet at a point $F$ inside the triangle. Prove that $A,N,F,P$ are concyclic.','The perpendicular bisectors invite the circumcentre, but connecting it to F needs an additional similarity or circle argument. The median condition must be used to force the final right angle.','usa_2008_9389ce')
add(2008,4,7,'Combinatorics',['geometry','triangulations','induction'],r'Find all integers $n\ge3$ for which a regular $n$-gon can be split into $n-2$ isosceles triangles using $n-3$ diagonals that do not cross in its interior.','Requires a recursive power-of-two lemma for a chain of vertices on a semicircle, then applying it around a triangle containing the centre. Both necessity and a matching triangulation must be proved.','usa_2008_2c2856')
add(2009,1,5.5,'Geometry',['power of a point','radical axis'],r'Circles $\omega_1,\omega_2$ meet at $X,Y$. A line through the centre of $\omega_1$ cuts $\omega_2$ at $P,Q$, and a line through the centre of $\omega_2$ cuts $\omega_1$ at $R,S$. If $P,Q,R,S$ are concyclic, prove that their circle’s centre lies on line $XY$.','The key is to recognize equal powers at the two given centres. Subtracting the resulting squared-distance identities proves the desired centre is on the radical axis.','usa_2009_e696dc')
add(2009,2,6.5,'Combinatorics',['sumsets','extremal','parity'],r'For a positive integer $n$, find the maximum size of a subset of $\{-n,-n+1,\ldots,n\}$ that has no elements $a,b,c$ with $a+b+c=0$. The three elements need not be distinct.','Splitting positive and negative elements and proving a sumset bound gives almost the result. The even case needs careful equality analysis or a separate pairing argument, followed by a sharp construction.','usa_2009_ddbe0d')
add(2009,4,5,'Algebra',['Cauchy-Schwarz','inequalities','extremal'],r'Positive real numbers $a_1,\ldots,a_n$, where $n\ge2$, satisfy $(\sum a_i)(\sum 1/a_i)\le(n+\tfrac12)^2$. Prove that $\max a_i\le4\min a_i$.','The useful Cauchy–Schwarz pairing swaps only the maximum and minimum in the reciprocal sum. This exposes their ratio; recognizing that pairing is the one substantial step.','usa_2009_2f9ce6')
add(2010,1,5,'Geometry',['Simson line','circle angles'],r'A convex pentagon $AXYZB$ is inscribed in a semicircle with diameter $AB$. Let $P,Q,R,S$ be the perpendicular projections of $Y$ onto lines $AX,BX,AZ,BZ$, respectively. If $O$ is the midpoint of $AB$, prove that the acute angle between $PQ$ and $RS$ equals $\tfrac12\angle XOZ$.','The two projection lines are Simson lines through the projection onto AB. Once that auxiliary point is added, two cyclic quadrilaterals convert the angle into an arc angle.','usa_2010_7b28d0')
add(2010,2,7,'Combinatorics',['invariants','cyclic order','induction'],r'$n$ students of distinct heights $h_1<\cdots<h_n$ stand in a circle, each facing the next student. Two neighbours may swap only when a student of height $h_k$ is directly behind one of height at most $h_{k-2}$. Prove that every sequence of permitted swaps has length at most $\binom n3$.','Ordinary inversion count fails on a circle. The solution tracks relative order among triples or uses a weighted circular potential; obtaining the sharp cubic bound is the main challenge.','usa_2010_30bc30')
add(2010,4,4.5,'Geometry',['incentre','irrationality','cosine rule'],r'In triangle $ABC$ with $\angle A=90^\circ$, the internal angle bisectors from $B,C$ meet the opposite sides at $D,E$ and meet one another at $I$. Can $AB,AC,BI,ID,CI,IE$ all have integer lengths? Prove your answer.','Identify I as the incentre and use its 135° angle. The cosine rule makes BC² irrational if BI and CI are integers, whereas Pythagoras makes it integral. The main step is choosing that triangle.','usa_2010_60d5ea')
add(2010,5,6.5,'Number Theory',['partial fractions','congruences','sums'],r'Let $p$ be an odd prime and $q=(3p-5)/2$. Set $S_q=\sum_{j=0}^{(p-3)/2}\frac1{(3j+2)(3j+3)(3j+4)}$. If $1/p-2S_q=m/n$ for integers $m,n$ with $n\ne0$, prove that $p\mid m-n$.','A partial-fraction decomposition must reorganize every third reciprocal into one interval. Pairing terms symmetrically around p then gives the modular statement while keeping denominators coprime to p.','usa_2010_73d4a3')
add(2011,1,5,'Algebra',['AM-GM','inequalities','homogenisation'],r'If $a,b,c>0$ and $a^2+b^2+c^2+(a+b+c)^2\le4$, prove $\frac{ab+1}{(a+b)^2}+\frac{bc+1}{(b+c)^2}+\frac{ca+1}{(c+a)^2}\ge3$.','Use the constraint to replace the constants, then recognize three fractions whose product is 1. The homogenization and regrouping are less obvious than the final AM–GM step.')
add(2011,2,7,'Combinatorics',['invariants','modular arithmetic','linear equations'],r'Integers at the vertices of a regular pentagon sum to $2011$. A move chooses an integer $m$, subtracts $m$ at two adjacent vertices, and adds $2m$ at the vertex adjacent to neither. Prove that exactly one vertex can be made to contain $2011$, with all other vertices containing $0$, by finitely many moves.','A weighted sum modulo 5 establishes uniqueness. Existence is a separate task: solve the move equations and show that the same congruence guarantees integral move sizes.','usa_2011_75d863')
add(2011,4,5.5,'Number Theory',['modular arithmetic','counterexamples','exponents'],r'Decide whether, for every integer $n\ge2$, the remainder when $2^{2^n}$ is divided by $2^n-1$ is a power of $4$. Either prove the assertion or give a counterexample with proof.','First reduce the huge exponent modulo n; the remainder is 2ʳ with r≡2ⁿ mod n. Finding an odd r requires testing beyond even n and primes; n=25 supplies a clean counterexample.','usa_2011_2692ef')
add(2011,5,6,'Geometry',['reflection','concurrency','angle chasing'],r'$P$ lies inside a convex quadrilateral $ABCD$. Interior points $Q_1,Q_2$ satisfy $\angle Q_1BC=\angle ABP$, $\angle Q_1CB=\angle DCP$, $\angle Q_2AD=\angle BAP$, and $\angle Q_2DA=\angle CDP$. Prove that $Q_1Q_2\parallel AB$ if and only if $Q_1Q_2\parallel CD$.','Reflecting P in the opposite sides reveals that both Q points lie on one perpendicular bisector. Constructing and proving that common locus is the insight; the parallel/concurrent conclusion then follows.','usa_2011_7e4182')
add(2011,6,6.5,'Combinatorics',['double counting','sets','construction'],r'A set $A$ has $225$ elements. Its subsets $A_1,\ldots,A_{11}$ each contain $45$ elements, and $|A_i\cap A_j|=9$ whenever $i\ne j$. Prove $|A_1\cup\cdots\cup A_{11}|\ge165$, and construct an example attaining equality.','Counting membership and pairs of memberships gives two moments. A quadratic nonnegative on integers sharpens the bound, and a construction using all 3-subsets of an 11-set proves equality.','usa_2011_2951fb')
add(2012,1,5.5,'Algebra',['Fibonacci numbers','triangle inequalities','construction'],r'Find all integers $n\ge3$ such that every list of $n$ positive real numbers with $\max a_i\le n\min a_i$ contains three entries that are the side lengths of an acute triangle.','Sort and square the entries. Failure of an acute triangle forces Fibonacci growth; the threshold and counterexamples come from comparing Fibonacci numbers with n².','usa_2012_25ac44')
add(2012,2,7,'Combinatorics',['pigeonhole principle','double counting','rotations'],r'Colour $432$ equally spaced points on a circle with four colours, using each colour exactly $108$ times. Prove that one can choose three points of each colour so that the resulting four monochromatic triangles are congruent.','Three successive rotation-averaging steps are needed. Excluding rotations already occupied by earlier colours improves the integer bounds from 27 to 28, then to 8 and finally 3; those small gains are essential.','usa_2012_9b4f1a')
add(2012,4,6.5,'Number Theory',['functional equations','factorials','divisibility'],r'Find every function $f:\mathbb N\to\mathbb N$ such that $f(n!)=f(n)!$ for all positive integers $n$, and $m-n\mid f(m)-f(n)$ whenever $m,n$ are distinct positive integers.','Small factorial inputs separate the constant cases. In the remaining case, unbounded fixed points from repeated factorials force f(n)=n by divisibility; recognizing that escape from local casework is the key step.')
add(2012,5,6.5,'Geometry',['Menelaus','reflection','sine rule'],r'Let $P$ be a point in the plane of triangle $ABC$, and let $\gamma$ be a line through $P$. Reflect lines $PA,PB,PC$ in $\gamma$ and let their intersections with $BC,CA,AB$ be $A^{\prime},B^{\prime},C^{\prime}$, respectively. Assuming these intersections are well-defined, prove that $A^{\prime},B^{\prime},C^{\prime}$ are collinear.','Menelaus suggests a product of directed ratios. Expressing each ratio by sines lets reflection pair and cancel the angles, but configuration signs require care.','usa_2012_283862')
add(2012,6,6,'Combinatorics',['double counting','inequalities','subset sums'],r'Let $n\ge2$ and real numbers $x_1,\ldots,x_n$ satisfy $\sum x_i=0$ and $\sum x_i^2=1$. For $A\subseteq\{1,\ldots,n\}$ put $S_A=\sum_{i\in A}x_i$. Prove that for every $\lambda>0$ there are at most $2^{n-3}/\lambda^2$ subsets with $S_A\ge\lambda$, and determine every equality case.','Sum the squares of all subset sums, cancel cross terms using the hypotheses, and pair complementary subsets. The equality classification adds a nontrivial final step beyond the counting bound.','usa_2012_06c2de')
add(2013,1,6,'Geometry',['Miquel point','similarity','circle angles'],r'Points $P,Q,R$ lie on sides $BC,CA,AB$ of triangle $ABC$. The circumcircles $(AQR),(BRP),(CPQ)$ meet line $AP$ again at $X,Y,Z$, respectively. Prove that $YX/XZ=BP/PC$.','Introducing the common Miquel point turns the ratios into two pairs of similar triangles. Finding that auxiliary point and matching the correct sides is the principal obstacle.','usa_2013_cd872c')
add(2013,4,6.5,'Algebra',['Cauchy-Schwarz','equality cases','radicals'],r'Find all real triples $x,y,z\ge1$ satisfying $\min\{\sqrt{x+xyz},\sqrt{y+xyz},\sqrt{z+xyz}\}=\sqrt{x-1}+\sqrt{y-1}+\sqrt{z-1}$.','Shift the variables by 1 and choose the minimum. Two nested Cauchy–Schwarz inequalities prove a universal bound; solving both equality conditions is needed to obtain the full parameterized family.')
add(2014,1,5,'Algebra',['polynomials','complex numbers','inequalities'],r'The real polynomial $P(t)=t^4+at^3+bt^2+ct+d$ has four real roots $x_1,\ldots,x_4$, counted with multiplicity, and $b-d\ge5$. Find the minimum of $\prod_{j=1}^4(x_j^2+1)$.','Evaluate the polynomial at i and −i to turn the product into (b−d−1)²+(a−c)². This is a useful but non-obvious algebraic encoding; the bound and an equality example are short.','usa_2014_e6bd00')
add(2014,3,6.5,'Algebra',['polynomials','coordinates','construction'],r'Construct distinct plane points $P_n$ for every integer $n$ such that, for any three distinct integers $a,b,c$, the points $P_a,P_b,P_c$ are collinear exactly when $a+b+c=2014$.','The construction needs a cubic curve whose intersection with a line has three x-coordinates with prescribed sum. Vieta’s formula then proves both directions, but inventing the curve is a significant insight.','usa_2014_eef9b1')
add(2021,1,5.5,'Algebra',['functional equations','induction','Pythagorean triples'],r'Find all functions $f:\mathbb N\to\mathbb N$ satisfying $f(a^2+b^2)=f(a)f(b)$ and $f(a^2)=f(a)^2$ for all positive integers $a,b$.','The Pythagorean identity (a²+b²)²=(a²−b²)²+(2ab)² propagates values equal to 1. A parity-based induction then reaches every positive integer.','usa_2021_1e2e48','USAJMO')
add(2021,2,5.5,'Geometry',['cyclic quadrilaterals','concurrency','rectangles'],r'Erect rectangles $BCC_1B_2$, $CAA_1C_2$, and $ABB_1A_2$ outside an acute triangle $ABC$. If $\angle BC_1C+\angle CA_1A+\angle AB_1B=180^\circ$, prove that $B_1C_2$, $C_1A_2$, and $A_1B_2$ concur.','The angle sum makes the three rectangle circumcircles share a point. Their right angles then place that point on all three desired lines; finding the circle interpretation is the key leap.','usa_2021_5ed82e','USAJMO',[{'competition':'USAMO','year':2021,'number':'1'}])
add(2021,4,6,'Combinatorics',['lattice geometry','extremal','construction'],r'Three labelled points $A,B,C$ start at $(0,0)$. In one move, one point moves one unit horizontally or vertically. What is the fewest moves required to make triangle $ABC$ have area $2021$? Prove optimality.','A bounding rectangle and AM–GM give the lower bound. It remains to find an exact-area lattice triangle meeting the bound; restricting to a right triangle gives a misleading larger answer.','usa_2021_57ea70','USAJMO')
add(2021,5,7,'Number Theory',['divisors','double counting','construction'],r'A finite set $S$ of positive integers has this property: for each $s\in S$ and every positive divisor $d\mid s$, exactly one $t\in S$ satisfies $\gcd(s,t)=d$. The elements $s,t$ may coincide. Determine all possible values of $|S|$.','The gcd map makes |S| equal a divisor count. Counting the fraction of elements divisible by a prime in two different ways forces squarefreeness; independent choices of paired primes supply all constructions.','usa_2021_2505cc','USAJMO',[{'competition':'USAMO','year':2021,'number':'4'}])
add(2021,6,5.5,'Algebra',['systems of equations','extremal','inequalities'],r'For an integer $n\ge4$, find all positive real numbers $a_1,\ldots,a_{2n}$ such that, with subscripts read modulo $2n$, $a_{2k-1}=1/a_{2k-2}+1/a_{2k}$ and $a_{2k}=a_{2k-1}+a_{2k+1}$ for $k=1,\ldots,n$.','Eliminate the odd-indexed terms, then apply the resulting relation at the minimum and maximum even terms. The two inequalities force equality throughout; this is much more accessible than its final-question position suggests.','usa_2021_609b2e','USAJMO',[{'competition':'USAMO','year':2021,'number':'5'}])
# Preserve Canada and any future Latin-American work.
json.dump(bank+rows,open(out,'w'),ensure_ascii=False,indent=2)
json.dump(rows,open(root/'research/americas/usa-assessed.json','w'),ensure_ascii=False,indent=2)
print('US unique included:',len(rows),'total:',len(bank+rows))
